-void setup()
-{
-  Serial.begin(9600);
-  // Check RECV_PIN to decide if we're RECEIVER or SENDER
-  if (digitalRead(RECV_PIN) == HIGH) {
-    mode = RECEIVER;
-    irrecv.enableIRIn();
-    pinMode(LED_PIN, OUTPUT);
-    digitalWrite(LED_PIN, LOW);
-    Serial.println("Receiver mode");
-  } 
-  else {
-    mode = SENDER;
-    Serial.println("Sender mode");
-  }
-}
-
